import * as T from 'https://esm.sh/three@0.150.1';
import {GLTFLoader} from 'https://esm.sh/three@0.150.1/examples/jsm/loaders/GLTFLoader.js';
(()=>{const mount=document.querySelector('.hero-image');if(!mount)return;
const scene=new T.Scene();scene.background=new T.Color(0x080e12);scene.fog=new T.FogExp2(0x080e12,.018);const camera=new T.PerspectiveCamera(36,1,.1,200);const renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=.95;renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.domElement.className='car-canvas';mount.prepend(renderer.domElement);scene.add(new T.HemisphereLight(0xbed5dc,0x090d0e,1.1));for(const [x,y,z,c,p]of [[-5,8,4,0xffffff,2.1],[5,7,-4,0x91d8e8,1]]){const light=new T.DirectionalLight(c,p);light.position.set(x,y,z);light.castShadow=true;light.shadow.mapSize.set(2048,2048);light.shadow.camera.left=-10;light.shadow.camera.right=10;light.shadow.camera.top=10;light.shadow.camera.bottom=-10;scene.add(light)}
let model,paint=[],dirty=0;const status=document.createElement('span');status.className='model-status';status.textContent='3D машин ачаалж байна…';mount.append(status);
const dirtUniform={value:1};function addRealDirt(mat){if(!mat.color||/glass|vitres|light|lamp/i.test(mat.name))return;mat.onBeforeCompile=shader=>{shader.uniforms.dirtAmount=dirtUniform;shader.vertexShader=shader.vertexShader.replace('#include <common>','#include <common>\nvarying vec3 vDirtPos;').replace('#include <begin_vertex>','#include <begin_vertex>\nvDirtPos=(modelMatrix*vec4(position,1.0)).xyz;');shader.fragmentShader=shader.fragmentShader.replace('#include <common>','#include <common>\nvarying vec3 vDirtPos; uniform float dirtAmount;\nfloat hash31(vec3 p){p=fract(p*.1031);p+=dot(p,p.yzx+33.33);return fract((p.x+p.y)*p.z);}\nfloat dirtNoise(vec3 p){vec3 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(mix(hash31(i),hash31(i+vec3(1,0,0)),f.x),mix(hash31(i+vec3(0,1,0)),hash31(i+vec3(1,1,0)),f.x),f.y),mix(mix(hash31(i+vec3(0,0,1)),hash31(i+vec3(1,0,1)),f.x),mix(hash31(i+vec3(0,1,1)),hash31(i+vec3(1,1,1)),f.x),f.y),f.z);}') .replace('#include <color_fragment>','#include <color_fragment>\nfloat coarse=dirtNoise(vDirtPos*2.8),flecks=dirtNoise(vDirtPos*35.0),streaks=dirtNoise(vec3(vDirtPos.x*12.0,vDirtPos.y*1.4,vDirtPos.z*12.0));float lower=1.0-smoothstep(.35,1.8,vDirtPos.y);float grime=coarse*.42+flecks*.24+streaks*.22+lower*.27;float mud=smoothstep(.37,.68,grime)*dirtAmount;diffuseColor.rgb=mix(diffuseColor.rgb,vec3(.38,.31,.23),mud*.9);');};mat.customProgramCacheKey=()=>`dirt-v2-${mat.name}`}
new GLTFLoader().load('urus_absoluttm.glb',g=>{model=g.scene;const bounds=new T.Box3().setFromObject(model),size=bounds.getSize(new T.Vector3()),center=bounds.getCenter(new T.Vector3());const scale=6.8/Math.max(size.x,size.z);model.scale.setScalar(scale);model.position.copy(center).multiplyScalar(-scale);model.position.y+=size.y*scale/2+.15;model.rotation.y=.55;model.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true;if(o.material){o.material=o.material.clone();addRealDirt(o.material);paint.push(o.material)}}});scene.add(model);camera.position.set(6.4,2.9,7.4);camera.lookAt(0,1,0);status.remove();apply(0)},undefined,()=>{status.textContent='3D загвар ачаалж чадсангүй'});
const ground=new T.Mesh(new T.PlaneGeometry(200,200),new T.MeshStandardMaterial({color:0x090d10,roughness:.32,metalness:.18}));ground.rotation.x=-Math.PI/2;ground.receiveShadow=true;scene.add(ground);const studio=new T.Group();scene.add(studio);const stripMat=new T.MeshBasicMaterial({color:0xd9eef2});for(let i=-2;i<=2;i++){const bar=new T.Mesh(new T.BoxGeometry(.045,.04,16),stripMat);bar.position.set(i*2.2,5.2,0);studio.add(bar)}const warm=new T.PointLight(0xff8d32,38,16);warm.position.set(-5,3,-2);scene.add(warm);
const resize=()=>{const w=mount.clientWidth,h=mount.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix()};new ResizeObserver(resize).observe(mount);resize();
function apply(p){dirty=1-p;dirtUniform.value=dirty;paint.forEach(m=>{if(m.roughness!==undefined){if(m.userData.baseRoughness===undefined)m.userData.baseRoughness=m.roughness;m.roughness=Math.min(1,m.userData.baseRoughness+dirty*.18)}})}const slider=mount.querySelector('.wash-control input');slider?.addEventListener('input',()=>apply(Number(slider.value)/100));
let dragging=false,last=0;renderer.domElement.addEventListener('pointerdown',e=>{dragging=true;last=e.clientX;renderer.domElement.setPointerCapture(e.pointerId)});renderer.domElement.addEventListener('pointermove',e=>{if(dragging&&model){model.rotation.y+=(e.clientX-last)*.009;last=e.clientX}});renderer.domElement.addEventListener('pointerup',()=>dragging=false);const animate=()=>{requestAnimationFrame(animate);renderer.render(scene,camera)};animate();})();
